  [1214006] = { "魔法の呪文と効果によるダメージと回復量を最大$N1増加させます。さらに呪文でクリティカルヒットを出す確率を$N2%上げます。", nil, 0x299ae61d, nil, "um" },
  [1214028] = { nil, "恐怖で逃げ惑っています。", nil, 0xfa67e4a8, "mu" },
