  [1214037] = { "周囲のすべての敵から生命力を吸い取ります。", "周囲のすべての敵から生命力を吸い取ります。", 0x035df0d3, 0x035df0d3, "uu" },
  [1214058] = { "Holy LightとFlash of Lightの呪文の回復量を$N1%増加させます。", nil, 0x11a2c394, nil, "um" },
  [1214059] = { "Chain HealとHealing Waveの呪文の回復量を$N1%増加させます。", nil, 0xd4e4189f, nil, "um" },
  [1214063] = { "Lifebloom、Nourish、Wild Growthの呪文の回復量を$N1%増加させます。", nil, 0xae757acd, nil, "um" },
  [1214069] = { "近接攻撃の命中時に一定の確率で、対象に$N1のFireダメージを与えます。SilithusのSilithid creaturesには、ほぼ毎回追加のダメージを与えます。", nil, 0x0d3fc4fc, nil, "um" },
  [1214070] = { "受けるすべてのダメージを$N1減少させます。", "受けるすべてのダメージが$N1減少します。", 0xa59be9ff, 0xa59be9ff, "uu" },
  [1214085] = { "Chaos Boltのクールダウンを$N1%短縮し、Chaos BoltとShadow Boltのダメージを$N2%増加させます。さらに、Chaos BoltがImproved Shadow Boltのタレントを発動できるようになり、そのチャージを$N3回追加します（Shadowflameによる追加チャージとは重複しません）。", nil, 0xa77caef7, nil, "um" },
  [1214087] = { "Conflagrateで対象に命中するたびに、$D1の間、与えるFireダメージが$N1%増加します。最大$N3回まで重なります。", nil, 0x4b1b6584, nil, "um" },
  [1214088] = { nil, "与えるすべてのFireダメージが$N1%増加します。", nil, 0x7f6cf186, "mu" },
  [1214091] = { "Shadow Cleaveのクールダウンを$D1短縮します。", nil, 0x39dc59b0, nil, "um" },
  [1214095] = { "悪魔のペットがいる間、犠牲にしたペットを再召喚しない限り、Demonic Sacrificeの効果が持続するようになります。Demonic Sacrificeの効果は一度に1つしか有効にできません。", nil, 0xc71dd522, nil, "um" },
