  [1214115] = { "直接の呪文ダメージを与えたとき一定の確率で、対象に$N1のFireダメージを与えます。SilithusのSilithid creaturesには、ほぼ毎回追加のダメージを与えます。", nil, 0xd8713e67, nil, "um" },
  [1214125] = { "直接呪文ダメージまたは近接攻撃時に一定の確率で、対象に$N1のFireダメージを与えます。SilithusのSilithidのクリーチャーには、ほぼ毎回追加のダメージを与えます。", nil, 0xe28b5229, nil, "um" },
  [1214136] = { "$D1後、効果を受けた全員で分け合う大ダメージを与えます。", "$D1後、効果を受けている全員で分け合う大ダメージを与えます。", 0x8a6f1acc, 0x8a6f1acc, "uu" },
