  [1214151] = { "Shadowcleaveを使った後$D1の間、Searing Painが近接範囲内の別の対象$N2体にも命中します。", nil, 0x6eaf27b8, nil, "um" },
  [1214155] = { "装備しているTimeworn防具の部位ごとに、すべての持続ダメージ呪文のダメージが$N1%増加します。", nil, 0x4e9d6f1a, nil, "um" },
