  [1214168] = { "武器に30分間持続する毒を塗ります。\n攻撃のたびに30%の確率で敵を毒に冒し、$D1かけて$N3のNatureダメージを与え、敵が受けるArcane、Fire、Frost、Nature、Shadowのダメージを$N5%増加させます。1体の対象に最大$N6回までスタックします。\n\nOccult PoisonはDeadly Poisonとして扱われ、Deadly Poisonで発動する、またはDeadly Poisonを強化するすべてのタレントと効果の恩恵を受けます。", nil, 0x88540c3c, nil, "um" },
  [1214169] = { "Occult Poison（Rank 2）を習得します。", nil, 0x212a53fa, nil, "um" },
