  [1214171] = { "武器に30分間持続する毒を塗ります。攻撃のたびに$N2%の確率で敵を毒に冒し、$D1かけて$N3のNatureダメージを与え、敵が受けるArcane、Fire、Frost、Nature、Shadowのダメージを$N5%増加させます。1体の対象に最大$N6回までスタックします。\n\nOccult PoisonはDeadly Poisonとして扱われ、Deadly Poisonで発動する、またはDeadly Poisonを強化するすべてのタレントと効果の恩恵を受けます。", nil, 0xdb56e997, nil, "um" },
  [1214179] = { "$D1の間、Furbolgに変身します。", "Furbolgに変身しています。", 0x9565f3ee, 0x105a6e3d, "uu" },
